package com.ruoyi.web.controller.equipment;
import java.net.URI;import java.net.URLDecoder;import java.nio.charset.StandardCharsets;import java.util.*;import javax.crypto.Mac;import javax.crypto.spec.SecretKeySpec;import org.springframework.jdbc.core.JdbcTemplate;
public class DingTalkSenderSelfTest {
 static class Db extends JdbcTemplate { public List<Map<String,Object>> queryForList(String sql){return List.of(Map.of("webhook","https://oapi.dingtalk.com/robot/send?access_token=test","secret","SECtest","keyword","维修"));} }
 static class Fake extends DingTalkSender { URI u; String b; Fake(){super(new Db());} @Override String post(URI u,String b){this.u=u;this.b=b;return "";} }
 public static void main(String[] args)throws Exception{var f=new Fake();if(!f.send("设备报修").isEmpty()||!f.b.contains("维修")||!f.b.contains("设备报修"))throw new AssertionError("keyword");var q=new HashMap<String,String>();for(String part:f.u.getRawQuery().split("&")){String[] v=part.split("=",2);q.put(v[0],URLDecoder.decode(v[1],StandardCharsets.UTF_8));}String t=q.get("timestamp");Mac m=Mac.getInstance("HmacSHA256");m.init(new SecretKeySpec("SECtest".getBytes(StandardCharsets.UTF_8),"HmacSHA256"));String expected=Base64.getEncoder().encodeToString(m.doFinal((t+"\nSECtest").getBytes(StandardCharsets.UTF_8)));if(!expected.equals(q.get("sign")))throw new AssertionError("signature");if(!f.parseResponse(200,"{\"errcode\":0}").isEmpty())throw new AssertionError("success");if(!f.parseResponse(200,"{\"errcode\":310000,\"errmsg\":\"bad keyword\"}").contains("310000"))throw new AssertionError("error");System.out.println("mock signature, keyword, success and error response passed");}
}
